import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WORKFLOW_DIR = path.join(__dirname, '..', '..', '..', 'workflow');

export const ACTIVE_WORKFLOW = '制图工作流.json';
export const PRO_WORKFLOW = '制图工作流-pro.json';
export const HIRES_WORKFLOW = '放大细化工作流.json';
export const HIRES_ADVANCED_WORKFLOW = '放大细化工作流-进阶.json';

function activePath() { return path.join(WORKFLOW_DIR, ACTIVE_WORKFLOW); }
function proPath() { return path.join(WORKFLOW_DIR, PRO_WORKFLOW); }
function hiresAdvancedPath() { return path.join(WORKFLOW_DIR, HIRES_ADVANCED_WORKFLOW); }
function hiresPath() { return path.join(WORKFLOW_DIR, HIRES_WORKFLOW); }

/**
 * 解析自定义工作流文件名 → 绝对路径。
 * 出于安全只接受 workflow/ 目录内的 .json 文件名（不含路径分隔符）。
 * 文件不存在、名字非法或非 .json 时返回 null，由调用方决定回退策略。
 */
export function resolveCustomWorkflowPath(filename) {
  if (!filename || typeof filename !== 'string') return null;
  if (filename.includes('/') || filename.includes('\\')) return null;
  if (!filename.toLowerCase().endsWith('.json')) return null;
  const p = path.join(WORKFLOW_DIR, filename);
  return fs.existsSync(p) ? p : null;
}

export function checkWorkflowHealth() {
  return {
    activeExists: fs.existsSync(activePath()),
    proExists: fs.existsSync(proPath()),
    hiresAdvancedExists: fs.existsSync(hiresAdvancedPath()),
    hiresExists: fs.existsSync(hiresPath()),
    dirExists: fs.existsSync(WORKFLOW_DIR),
  };
}

export function ensureWorkflowDir() {
  if (!fs.existsSync(WORKFLOW_DIR)) fs.mkdirSync(WORKFLOW_DIR, { recursive: true });
}

export function restoreWorkflow() {
  ensureWorkflowDir();
  fs.writeFileSync(activePath(), WORKFLOW_TEMPLATE_TURBO, 'utf8');
  fs.writeFileSync(proPath(), WORKFLOW_TEMPLATE_BASE, 'utf8');
  fs.writeFileSync(hiresPath(), WORKFLOW_TEMPLATE_HIRES, 'utf8');
  fs.writeFileSync(hiresAdvancedPath(), WORKFLOW_TEMPLATE_HIRES_ADVANCED, 'utf8');
  console.log(`[workflowTemplates] Restored ${ACTIVE_WORKFLOW} (turbo) + ${PRO_WORKFLOW} (base) + ${HIRES_WORKFLOW} + ${HIRES_ADVANCED_WORKFLOW} (hires)`);
  return { ok: true };
}

export function autoRestoreMissing() {
  ensureWorkflowDir();
  const result = {};
  if (!fs.existsSync(activePath())) {
    fs.writeFileSync(activePath(), WORKFLOW_TEMPLATE_TURBO, 'utf8');
    console.log(`[workflowTemplates] Auto-restored ${ACTIVE_WORKFLOW} (turbo)`);
    result.active = 'restored';
  } else {
    result.active = 'skipped';
  }
  if (!fs.existsSync(proPath())) {
    fs.writeFileSync(proPath(), WORKFLOW_TEMPLATE_BASE, 'utf8');
    console.log(`[workflowTemplates] Auto-restored ${PRO_WORKFLOW} (base)`);
    result.pro = 'restored';
  } else {
    result.pro = 'skipped';
  }
  if (!fs.existsSync(hiresPath())) {
    fs.writeFileSync(hiresPath(), WORKFLOW_TEMPLATE_HIRES, 'utf8');
    console.log(`[workflowTemplates] Auto-restored ${HIRES_WORKFLOW} + ${HIRES_ADVANCED_WORKFLOW} (hires)`);
    result.hires = 'restored';
  } else {
    result.hires = 'skipped';
  }
  if (!fs.existsSync(hiresAdvancedPath())) {
    fs.writeFileSync(hiresAdvancedPath(), WORKFLOW_TEMPLATE_HIRES_ADVANCED, 'utf8');
    result.hiresAdvanced = 'restored';
  } else {
    result.hiresAdvanced = 'skipped';
  }
  return result;
}


